# -*- coding: utf-8 -*-
"""C0422 fig-/fing-/fict-: concrete shaping, imagined stories, forms and feigning."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
def A(h,w,m):return h+[[w,m]]
B=[['拉丁 fingere，分词 fictus','塑造、制成；也指编造、假装']]
FIG=[['拉丁 figura（与 fingere 同族）','形状、形象；表达的形式']]
FIGURE=FIG+[['古法语 figure → 中古英语 figure','形状、形体；数字符号'],['英语 figure〔名词〕','人影、人物、图形、数值等可被描画或表达的形式']]
FIGURATIVE=FIG+[['拉丁 figurare → 晚期拉丁 figurativus','塑造 → 借形象表达的'],['法语 figuratif／直接拉丁借入 → 英语 figurative','语言中比喻的；艺术中具象的']]
FICTION=B+[['拉丁 fictio／fictionem → 古法语 ficcion；另有直接拉丁借入','塑造、编造出的东西'],['中古英语 ficcioun → 英语 fiction','想象创作；小说、虚构故事；捏造']]
FICTIONAL=A(FICTION,'英语 fiction + -al → fictional','属于虚构故事或小说的')
FICTIONALIZE=A(FICTIONAL,'英语 fictional + -ize → fictionalize','把素材作小说化、虚构化处理')
CONFIGLAT=FIG+[['拉丁 figurare → configurare（con- + figurare）','塑造 → 按一定形式安排、构成']]
CONFIG=CONFIGLAT+[['法语 configurer／直接拉丁借入 → 英语 configure','安排形状；后来设置系统的组成和选项']]
CONFIGURATION=CONFIGLAT+[['晚期拉丁 configuratio／configurationem → 法语 configuration／直接拉丁借入','各部分安排形成的形态'],['英语 configuration','结构、布局；设备或软件的配置']]
DISFIGURE=FIG+[['拉丁 figurare → 中世纪拉丁 diffigurare','塑造 → 破坏、改变外形；dis- 在 f 前同化'],['古法语／盎格鲁法语 desfigurer → 中古英语 disfiguren → disfigure','损坏外貌、形状']]
TRANSFIGLAT=FIG+[['拉丁 figurare → transfigurare','塑造 → 改变形状、面貌']]
TRANSFIG=TRANSFIGLAT+[['古法语 transfigurer／直接拉丁借入 → 中古英语 transfiguren','改变形貌；早期常用于宗教语境'],['英语 transfigure','使面貌大变，常含光彩或美感的提升']]
FEIGN=B+[['古法语 feindre → 中古英语 feinen／feynen','做出某种样子；假装'],['英语改拼 feign','g 反映法语 feign- 词干及拉丁词形影响，读音不发 g']]
FAINT=B+[['古法语 feindre → 分词 faint／feint','假装、畏缩等旧义 → 虚假、软弱等分词义'],['中古英语 faint → 英语 faint','虚弱；微弱难察觉；另有动词晕倒']]
W=[
E('figure','英 /ˈfɪɡə/；美 /ˈfɪɡjər/，美式也读 /ˈfɪɡər/','数字、数值；人物、人影、体形；图形；认为、估计；弄明白〔figure out〕','最早抓“呈现出的形式”：人显出身影，线条围成图形，数字写成符号；再从用数字计算，走向心里推算、弄明白。','名词来自古法语 figure、拉丁 figura；动词另经古法语 figurer 接拉丁 figurare“塑造、表现”。现代 figure out 接计算、思考这条支线；不是把一切意思都硬译成“形状”。',FIG+[['拉丁 figura → 古法语 figure → 英语 figure〔名词〕','形态、符号 → 数字、人形、图示等'],['并行：拉丁 figurare → 古法语 figurer → 英语 figure〔动词〕','塑造、描绘 → 心中想象、计算、认为']],'sales figures 是销售数据；a public figure 是公众人物；Figure 2 是图二。I figure... 常说我估计、我认为；figure out the problem 是想明白问题。That figures 表示那就说得通了，常带“果然如此”的语气。','sales figures；a leading figure；a human figure；figure out；figure that；That figures。','number 更直接说数字或数量；figure 常用于报告中的数值或有意义的数字。figure out 强调通过思考解决，find out 更泛指获知。',('The latest sales figures are shown in Figure 2.','最新销售数据见图二。'),('A tall figure stood at the end of the platform.','站台尽头站着一个高高的人影。'),('I finally figured out why the door would not close.','我终于弄明白门为什么关不上了。'),('I figure we can finish the work before lunch.','我估计我们午饭前能把工作做完。'),sources=[S('figure'),K('figure'),O('figure_1'),O('figure_2')]),
E('figurative','英 /ˈfɪɡərətɪv/；美 /ˈfɪɡjərətɪv/','比喻的；借形象表达的；具象的〔艺术〕','语言里是用一个画面表达另一层意思；艺术里则是画面中能认出人物、动物或物体，和纯抽象形式相对。','接晚期拉丁 figurativus，来自 figurare“塑造”，经法语 figuratif 等进入英语。现代可与 figure 的形象、修辞用法对照，但不是新造的 figure + -ative。',FIGURATIVE,'a figurative expression 可把繁忙生活说成一场赛跑，并非真在赛道上。figurative art 则是具象艺术：对象可以变形、风格化，仍能辨认，不必画得像照片。','figurative language；a figurative meaning；figurative art；a figurative painter。','语言里的 figurative 常与 literal“字面的”对照；艺术里的 figurative 常与 abstract“抽象的”对照。不同领域要换一组参照。',('Calling the office a jungle is a figurative description of its fierce competition.','把办公室称作丛林，是在比喻其中竞争激烈。'),('The exhibition brings together abstract paintings and figurative portraits.','这场展览同时展出抽象画和具象肖像画。'),sources=[S('figurative'),K('figurative'),O('figurative'),'https://www.nationalgalleries.org/art-and-artists/glossary-terms/figurative-art']),
E('figuratively','英 /ˈfɪɡərətɪvli/；美 /ˈfɪɡjərətɪvli/','用比喻来说；在比喻意义上','提醒对方把刚才的话当作一个画面来理解，而不是照字面想象真的发生了什么。','figurative + -ly，英语副词；继承 figurative 在修辞中的比喻义。',A(FIGURATIVE,'英语 figurative + -ly → figuratively','以比喻方式、在比喻层面'),'figuratively speaking 常放在句首或补在夸张表达后。说 someone carries a mountain of work 是形容工作很多，figuratively 可以把这层意思明确出来。','figuratively speaking；use a word figuratively；literally and figuratively。','literally 本义指照字面；figuratively 明确指出比喻。口语里 literally 也常被用来加强语气，但正式区分两者仍有用。',('Figuratively speaking, she carried the whole project on her shoulders.','打个比方说，整个项目的重担都压在她肩上。'),('The word bridge is used figuratively to mean a connection between communities.','这里的 bridge 是比喻用法，指不同群体之间的联系。'),sources=[K('figuratively'),O('figuratively'),S('figurative')]),
E('figurehead','英 /ˈfɪɡəhed/；美 /ˈfɪɡjərhed/','船首雕像；有名位而无实权的领袖、象征人物','船最前面的雕像看起来像在领路，却不掌舵；由此可以理解一个组织里名义上居首、实际不作主的人。','英语 figure“雕像、形象” + head“前端、头部”，先指船首装饰像，后来比喻缺乏实际权力的名义领袖。',FIGURE+[['英语 figure + head → figurehead','装在船首的雕像'],['英语比喻 figurehead','代表组织的名义领袖；通常缺乏实际控制力']],'a ceremonial figurehead 可说主要承担礼仪象征作用的人；a mere figurehead 往往强调只是摆在台前。有时作用重要，只是不负责实际决策。','a ceremonial figurehead；a mere figurehead；serve as a figurehead；a ship’s figurehead。','leader 可以有实际领导权；figurehead 通常特别指出象征性地位与实际控制之间的落差，不等于一般公众人物 public figure。',('The museum restored the wooden figurehead from an old sailing ship.','博物馆修复了一艘旧帆船的木制船首像。'),('He remained a figurehead while the committee made all major decisions.','他仍是名义领袖，而所有重大决定都由委员会作出。'),sources=[S('figurehead'),K('figurehead'),O('figurehead')]),
E('fiction','/ˈfɪkʃən/','小说、虚构文学；虚构的事；捏造','用材料捏出一个物体，换成用想象造出人物和故事，就是这条词义路；造出的故事可以有价值，并不因此等于骗人。','拉丁 fictio、宾格 fictionem 来自 fingere 的分词词干 fict-，原有塑造、编造之意；经古法语 ficcion 或直接拉丁借入，成为英语 fiction。',FICTION,'书店里的 fiction 是虚构文学类别，通常不可数；a convenient fiction 则是一种大家暂且接受、实际上并不真实的说法。要看它在谈创作还是批评事实失真。','read fiction；historical fiction；science fiction；a work of fiction；fact and fiction。','fiction 不等于谎言：小说读者通常知道它是创作。lie 侧重故意把不真实内容当真话说；nonfiction 则以现实人物、事件和知识为材料。',('She writes historical fiction set in a small coastal town.','她写以一座沿海小城为背景的历史小说。'),('The claim that nobody had noticed the problem was a convenient fiction.','所谓从来没人注意到这个问题，不过是个方便搪塞的说法。'),sources=[S('fiction'),K('fiction'),O('fiction')]),
E('fictional','/ˈfɪkʃənəl/','虚构故事中的；小说式的、虚构的','人物和地点属于作者创造的世界；即使取材于现实，也没有承诺每个细节都能在真实世界找到一模一样的对应物。','英语 fiction + -al，形成与虚构文学、故事有关的形容词。比早已有的 fictitious 更明确地与 fiction 这一类别相配。',FICTIONAL,'a fictional character 是虚构人物；a fictional town 是作者设置的小镇。fictional 可以很中性，告诉读者作品性质，而不是指责作者作假。','a fictional character；a fictional world；a fictional account；a fictional setting。','fictional 常谈故事中的虚构；fictitious 更常强调名字、资料、说法并不存在或是编造的。两者有重叠，不能只按“虚构”两个字机械替换。',('The novel takes place in a fictional town near the sea.','小说发生在一座虚构的海滨小镇。'),('The detective is fictional, but many of the locations are real.','侦探是虚构人物，但许多地点是真实的。'),sources=[S('fictional'),K('fictional'),O('fictional')]),
E('fictitious','/fɪkˈtɪʃəs/','虚构的；编造的；并不真实存在的','表格里似乎有这个人，故事里似乎有这家公司，但那只是人为造出来的名字或细节。','拉丁 fingere 的分词 fictus 形成 ficticius“人为制作、虚构的”，中世纪拼写 fictitius 影响英语 fictitious。它不是由英语 fiction 直接换后缀造出。',B+[['拉丁 fictus → ficticius；中世纪写法 fictitius','塑造、编造的 → 人造、虚构的'],['英语 fictitious','编造的、不实际存在的']],'a fictitious name 可以为了隐私而使用，也可能用于欺骗；fictitious expenses 则通常暗示虚报费用。是否带欺诈意味，要看场景和说话者评价。','a fictitious name；a fictitious address；fictitious characters；fictitious claims。','imaginary 强调想象而非现实；fictitious 更容易让人想到人为编造的资料或故事。fictitious 本身并不保证编造是恶意的。',('All customer names in the training file are fictitious.','培训文件里的所有客户姓名都是虚构的。'),('The investigation uncovered several fictitious expense claims.','调查发现了几笔虚报的报销申请。'),sources=[S('fictional'),K('fictitious'),O('fictitious')]),
E('fictionalize','/ˈfɪkʃənəlaɪz/','把……小说化；对真实素材作虚构处理','保留一些真实经历作为底子，再改人物、补对白、合并事件，让材料成为一个故事。','fictional + -ize，英语动词；英式也写 fictionalise。这里的动作不是单纯记录事实，而是主动把素材改写成带虚构成分的作品。',FICTIONALIZE,'fictionalize someone’s life 是把人生经历小说化；a fictionalized account 是经过虚构处理的叙述。它可以公开说明创作方法，不必暗中伪装成历史记录。','fictionalize an event；fictionalize a life；a fictionalized account。','document 尽量记录资料与证据；fictionalize 允许创作性改动。两者可能使用同一事件作素材，但作品对事实的承诺不同。',('The film fictionalizes several events from the musician’s early life.','电影对这位音乐家早年的几件事作了虚构化改编。'),('She chose to fictionalize the story rather than use her relatives’ real names.','她选择把故事小说化，没有使用亲属的真名。'),sources=[S('fictionalize'),K('fictionalize'),M('fictionalize'),O('fictionalize')]),
E('fictionalization','英 /ˌfɪkʃənəlaɪˈzeɪʃən/；美 /ˌfɪkʃənələˈzeɪʃən/','小说化、虚构化处理；经过这种处理的作品','把真实材料变成故事的那一步，或已经这样改写出来的版本；讨论重点往往是哪些部分改了、为何要改。','fictionalize + -ation，英语动作或结果名词，拼写去末尾 e 后形成 -ization；英式也写 fictionalisation。',A(FICTIONALIZE,'英语 fictionalize + -ation → fictionalization','虚构化的过程；相应叙述或作品'),'the fictionalization of history 说历史被作故事化、虚构化处理；a fictionalization of the trial 是以那场审判为底子的创作版本。', 'the fictionalization of；a dramatic fictionalization；the process of fictionalization。','fiction 是宽泛类别；fictionalization 往往指明从一份材料、经历或事件改写而来的过程，不只是任何从零想出的故事。',('The author’s note explains the fictionalization of several family events.','作者后记说明了几段家庭经历是如何被虚构化处理的。'),('The novel is a fictionalization of the expedition, not a transcript of its records.','这部小说是对那次远征的虚构改写，并非远征记录的逐字重现。'),sources=[S('fictionalization'),S('fictionalize'),K('fictionalization'),M('fictionalization')]),
E('figment','/ˈfɪɡmənt/','凭空想出的事物；想象的产物','脑中已经把它“捏”出来，现实中却未必有那个东西；这个词通常提醒人别把想象直接当事实。','借入拉丁 figmentum“制成、造出的东西”，接 fingere“塑造、编造”与名词成分 -mentum。不能拆成英语 fig“无花果”加 -ment。',B+[['拉丁 figmentum → 英语 figment','造出的东西 → 想象或编造出来的东西']],'最常见是 a figment of someone’s imagination。说某物是 figment，通常是在否认它现实存在；所以它比普通 idea“想法”更带质疑。','a figment of the imagination；a mere figment；a figment of someone’s mind。','fiction 可以是一部公开承认虚构的作品；figment 更像其中一个并不存在的想象物。a figment of imagination 中通常用 the 或所有格限定 imagination。',('The monster turned out to be a figment of the child’s imagination.','那个怪物原来只是孩子想象出来的。'),('The narrator insists that the stranger was real, not a figment of his imagination.','叙述者坚持说那个陌生人确实存在，不是他凭空想出来的。'),sources=[S('figment'),K('figment'),O('figment')]),
E('figurine','英 /ˌfɪɡəˈriːn/；美 /ˌfɪɡjəˈriːn/','小雕像；人物或动物小塑像','放在架子上、柜子里的小型形象：它像一个人或一只动物，通常供装饰、收藏或展示。','拉丁 figura → 意大利 figura 的小称 figurina → 法语 figurine → 英语。现代可看出 figure 的亲缘，但不是英语 figure 当场加 -ine。',FIG+[['意大利 figura → 小称 figurina → 法语 figurine','形象 → 小型塑像'],['英语 figurine','小雕像、装饰性塑像']],'a porcelain figurine 是瓷质小像；an animal figurine 是动物小塑像。它强调大小和形象，不限定必须手工雕刻，也不限定一定贵重。','a porcelain figurine；a clay figurine；collect figurines；an animal figurine。','statue 常让人想到较大的雕像；figurine 通常小得可陈列、收藏。figure 范围更广，还能指图形、数字和人物。',('A tiny porcelain figurine stood beside the lamp.','灯旁摆着一尊小小的瓷像。'),('The museum displayed clay figurines shaped like birds.','博物馆展出了几件鸟形陶塑。'),sources=[S('figurine'),K('figurine'),O('figurine')]),
E('effigy','/ˈefɪdʒi/','某人的雕像、塑像；代表某人的人形像','做出一个人的替身形象，让它代表那个人；可以用于纪念，也可以在抗议中代表被批评的对象。','拉丁 ex- 与 fingere 组成 effingere“塑造、表现”，ex- 在 f 前同化为 ef-；相关名词 effigies 经法语 effigie 或直接拉丁借入英语。',B+[['拉丁 ex- + fingere → effingere → effigies','塑造出来 → 人物形象、复制像'],['法语 effigie／直接拉丁借入 → 英语 effigy','代表某人的雕像或人形替身']],'a stone effigy 可以是墓碑上的人物雕像；in effigy 表示通过那个人的替身像来做某种象征性行为。不能一看到 effigy 就断定有人真的受到同样伤害。','an effigy of；a stone effigy；a funeral effigy；in effigy。','statue 主要说雕像本身；effigy 更强调它代表谁。figurine 通常强调小巧，effigy 并不由尺寸定义。',('A stone effigy of the knight lies on top of the tomb.','墓上平放着一尊骑士石像。'),('The protesters carried a cardboard effigy of the unpopular governor.','抗议者抬着一尊纸板制作的州长人形像，表达对他的不满。'),sources=[S('effigy'),K('effigy'),O('effigy')]),
E('feign','/feɪn/','假装；装出〔情绪、状态〕','实际没有那种感觉，却把脸色、声音或动作摆出来，让别人以为你有。','拉丁 fingere“塑造、编造”经古法语 feindre 到中古英语 feinen、feynen。后来改拼 feign，g 反映法语词干和拉丁拼写影响，今天不发音。',FEIGN,'feign surprise 是装作吃惊；feign ignorance 是明明知道却装不知道。常直接接名词，不必加 be；比 pretend 更正式，常强调故意装出的状态。','feign surprise；feign interest；feign ignorance；feign innocence。','pretend 范围更广，可接 to do；feign 更常直接接某种情绪或状态。不要把 feign 读成带 /ɡ/ 的两个音节。',('He feigned interest in the conversation while checking the clock.','他一边看钟，一边装作对谈话很感兴趣。'),('She could not feign surprise because she already knew the news.','她早已知道消息，没法装出吃惊的样子。'),sources=[S('feign'),K('feign'),O('feign')]),
E('feigned','/feɪnd/','假装出来的；佯装的','外表已经做出那种表情或态度，但叙述者告诉你：那并不是真实感受。','feign + -ed，过去式、过去分词及形容词；g 仍不发音，-ed 读 /d/，合起来只有一个音节。',A(FEIGN,'英语 feign + -ed → feigned','已经装出的；并非真心或真实的'),'feigned surprise 说装出来的惊讶；feigned indifference 是佯装不在乎。形容词直接给表现加上真实性判断，而 ordinary surprise 不带这种判断。','feigned surprise；feigned innocence；feigned indifference；feigned enthusiasm。','faint 表示微弱或晕倒，feigned 表示假装出来的。a faint smile 是淡淡一笑，a feigned smile 才是装出来的笑。',('She greeted the announcement with feigned enthusiasm.','她听到宣布后装出热情的样子。'),('His feigned indifference did not hide his disappointment.','他佯装不在乎，却没能掩饰失望。'),sources=[K('feigned'),O('feigned'),S('feign')]),
E('feint','/feɪnt/','假动作；佯攻；做假动作','先摆出要往一个方向行动的样子，让对方作出反应，真正动作再转向别处。','名词借法语 feinte，由 feindre“假装”的阴性分词名词化；远接拉丁 fingere。现代“做假动作”动词由这个名词发展，旧英语另有同形的虚弱、假装义，今天不必混用。',B+[['古法语 feindre → 阴性分词 feinte，名词化','假装 → 假装的行动、假动作'],['法语 feinte → 英语 feint〔名词〕','迷惑对手的假动作'],['英语 feint〔动词〕','做假动作、佯攻']],'make a feint 是做一个假动作；feint to the left 是虚晃向左。体育和军事描写都可见，也可比喻只为转移注意的举动。','make a feint；a feint to the left；feint towards；a tactical feint。','feign 常装情绪或状态；feint 更常是误导对手的动作。faint 与 feint 同音，却在现代英语中主要说微弱、昏厥。',('The player made a feint to the left and then moved right.','球员向左虚晃一下，随后转向右边。'),('The boxer feinted with his left hand before stepping back.','拳击手用左手做了个假动作，然后向后退了一步。'),sources=[S('feint'),K('feint'),O('feint_1'),O('feint_2')]),
]
W += [
E('faint','/feɪnt/','微弱的、不清楚的；晕乎乎的、快昏倒的；晕倒','光、声音、痕迹都弱到快察觉不到；用在人身上，是觉得力气和清醒感快撑不住了。','来自古法语 faint／feint，接 feindre“假装”的分词；旧法语还发展出软弱、畏缩等义，英语沿虚弱这条路走向微弱、昏厥。动词 faint 从形容词发展，今天晕倒并不表示假装。',FAINT+[['英语形容词 faint → 动词 faint','虚弱、昏沉 → 短暂失去意识']],'a faint sound 是微弱的声音；a faint chance 是很小的可能；feel faint 是觉得快昏倒，faint 作动词才表示昏倒。a faint smile 通常只是淡淡的笑，并不说明虚假。','a faint sound；a faint smell；a faint smile；feel faint；faint from exhaustion。','faint 与 feint 同音，但 feint 是假动作。feigned 才明确表示装出来的；词源相连不代表今天的词义相同。',('We could hear a faint sound coming from the next room.','我们能听见隔壁传来一点微弱的声音。'),('There is still a faint chance that the missing letter will turn up.','那封丢失的信仍有一点点可能被找到。'),('The character feels faint and then faints before reaching the chair.','故事中的人物先感到一阵晕眩，还没走到椅子旁就昏倒了。'),sources=[S('faint'),K('faint'),O('faint_1'),O('faint_2'),'https://www.nhs.uk/symptoms/fainting/']),
E('faintly','/ˈfeɪntli/','微弱地、隐约地；有一点儿、略微','不是完全没有，而是只有一点痕迹：声音勉强听见，颜色不明显，某种感觉轻轻地冒出来。','faint + -ly；早期英语已有对应副词形式，随 faint 的虚弱、微弱义发展出现代的隐约、略微用法。',A(FAINT,'英语 faint + -ly → faintly','微弱地；以很小的程度'),'hear something faintly 是隐约听见；faintly amused 是略感好笑；faintly ridiculous 是有点荒唐。这些搭配里的 faintly 表示程度，不是“晕倒地”。','glow faintly；smile faintly；faintly familiar；faintly amused。','quietly 强调安静或声音轻；faintly 强调接收者感受到的信号很弱。a faintly familiar face 是有些面熟，并不表示脸色很淡。',('A small light glowed faintly at the end of the corridor.','走廊尽头有一盏小灯隐隐发亮。'),('The old tune sounded faintly familiar to her.','她觉得那首老曲子听着有点耳熟。'),sources=[S('faintly'),K('faintly'),O('faintly')]),
E('faintness','/ˈfeɪntnəs/','眩晕欲倒的感觉；微弱、不清晰','一种是人感到快撑不住、快晕过去；另一种是某个信号太弱，比如字迹淡到不好辨认。','faint + -ness，把形容词的状态变成名词；中古英语已有相应形式。理解时要看它谈身体感觉，还是声音、光线、颜色等的微弱。',A(FAINT,'英语 faint + -ness → faintness','虚弱、昏沉的状态；信号微弱的程度'),'a feeling of faintness 是一阵将要昏倒的感觉；the faintness of the writing 则说字迹浅淡。出现 faintness 不等于已经发生了动词 faint 所说的昏厥。','a feeling of faintness；a spell of faintness；the faintness of a sound；the faintness of the print。','fainting 指昏倒这个事件；faintness 可以只说昏沉感，也可完全不涉及人体。weakness 范围更宽，可说肌肉、能力、论证等的薄弱。',('She described a sudden feeling of faintness to the doctor.','她向医生描述了突然感到快要昏倒的那阵感觉。'),('The faintness of the pencil marks made the map hard to read.','铅笔痕迹太淡，地图很难看清。'),sources=[K('faintness'),M('faintness'),S('faint')]),
E('configure','英 /kənˈfɪɡə/；美 /kənˈfɪɡjər/','配置；设置；安排各部分的组合','零件和选项已经有了，你把它们排成能按需要工作的样子：选哪种连接、启用哪些功能、各部分怎么配合。','拉丁 con- 与 figurare“塑造”组成 configurare，经法语 configurer 或直接拉丁借入英语。现代计算机用法承接的是安排各部分形成某种结构，不是“给电脑画图”。',CONFIG,'configure a router 是配置路由器；configure an app to do something 是设定应用按某方式运行。也可谈座椅、设备等的排列，只是软件和硬件语境尤其常见。','configure a system；configure settings；configure something to do；configure something for。','install 说安装；configure 说调整组成与设置。安装完成的软件可能还需要 configure，才能适合实际用途。',('The assistant helps you configure the app for a second language.','设置助手会帮助你把应用配置为支持第二种语言。'),('The room can be configured for either a lecture or a small workshop.','房间可以布置成讲座形式，也可以布置成小型工作坊形式。'),sources=[S('configure'),K('configure'),O('configure'),M('configure')]),
E('configured','英 /kənˈfɪɡəd/；美 /kənˈfɪɡjərd/','已配置的；按某种方式设置好的','选项和组合已经调过，现在强调系统实际处于哪种设置状态。','configure + -ed，末尾已有 e，只加 d；过去式、过去分词，也常作描述状态的形容词。-ed 在这里读 /d/。',A(CONFIG,'英语 configure + -ed → configured','已经配置；具有某种设置'),'be configured to do 表示被设置成会做某事；properly configured 是配置得当。configured 本身不保证配置正确，还可以说 incorrectly configured。','configured to do；configured for；properly configured；incorrectly configured。','configurable 表示可以调；configured 表示已经调成某种状态。前者谈能力，后者谈当前结果。',('The dashboard is configured to show only the current month.','仪表板被设置为只显示本月数据。'),('A correctly configured device should display the local time.','配置正确的设备应当显示当地时间。'),sources=[K('configured'),M('configured'),S('configure')]),
E('configuration','英 /kənˌfɪɡəˈreɪʃən/；美 /kənˌfɪɡjəˈreɪʃən/','配置；布局；各部分的组合方式','把同一批东西换个摆法、换组设置，整体就会不同；configuration 说的就是这个具体组合。','接晚期拉丁 configuratio、configurationem，来自动词 configurare；经法语或直接拉丁借入英语。名词有自己的借入路线，并非从现代英语 configure 才开始形成。',CONFIGURATION,'a configuration file 保存系统设置；the seating configuration 是座位布局；different hardware configurations 是不同的硬件组合。它既能指配置过程，也常指配置后的结构或一组参数。','a configuration file；the default configuration；hardware configuration；seating configuration。','setting 可以只是一个选项；configuration 往往说多个选项或部件组成的整体。layout 更强调可见的空间布局。',('Save the current configuration before changing the network settings.','修改网络设置前，先保存当前配置。'),('The new seating configuration leaves more space near the entrance.','新的座位布局在入口附近留出了更多空间。'),sources=[S('configuration'),K('configuration'),O('configuration')]),
E('configurable','英 /kənˈfɪɡərəbl/；美 /kənˈfɪɡjərəbl/','可配置的；可以按需调整设置的','产品没有把所有选择固定死，而是留出选项，让不同用户把它调成适合自己的样子。','configure + -able，去末尾 e 后加后缀，表示能够被配置。重点在可调整的能力，不表示已经完成配置。',A(CONFIG,'英语 configure + -able → configurable','允许调整组成、布局或设置的'),'a configurable dashboard 可以选择显示哪些内容；user-configurable 常说用户自己能调的。可配置到什么程度，要看产品实际提供的选项。','highly configurable；a configurable interface；configurable options；a configurable dashboard。','customizable 范围更宽，可能连外观、功能都允许改；configurable 常聚焦已有选项怎样组合，不一定可以任意开发新功能。',('The dashboard is configurable, so each team can choose its own charts.','仪表板可以配置，因此每个团队都能选择自己要看的图表。'),('The software includes configurable reminders for upcoming tasks.','软件提供可调整的提醒功能，用于提示即将到来的任务。'),sources=[K('configurable'),M('configurable'),S('configure')]),
E('reconfigure','英 /ˌriːkənˈfɪɡə/；美 /ˌriːkənˈfɪɡjər/','重新配置；重新安排结构','原来的排列或设置已经存在，现在为了新的目的，把它重新组合一遍。','re-“重新” + configure，是英语构词。重新配置不必换掉所有零件，也不必恢复出厂状态。',A(CONFIG,'英语 re- + configure → reconfigure','把已有系统、布局重新安排'),'reconfigure a network 是改网络的配置；reconfigure a room 是重新安排空间。使用时通常能说清改变是为了什么，例如更多座位、不同工作流程。','reconfigure a system；reconfigure a network；reconfigure the layout；reconfigure for。','reset 常指重设、恢复某种起始状态；reconfigure 强调换成另一套配置，新状态未必是原始默认状态。',('We reconfigured the meeting room to make space for group discussions.','我们重新布置了会议室，为分组讨论腾出空间。'),('The software must be reconfigured when the server address changes.','服务器地址变化时，必须重新配置软件。'),sources=[S('reconfigure'),K('reconfigure'),O('reconfigure')]),
E('reconfiguration','英 /ˌriːkənˌfɪɡəˈreɪʃən/；美 /ˌriːkənˌfɪɡjəˈreɪʃən/','重新配置；结构重组','强调从旧的安排变成新安排这件事，也可以说重排以后形成的新结构。','英语 re- + configuration；与 reconfigure“重新配置”在现代用法中配套，但名词可直接从 configuration 加前缀形成，无须画成英语动词再回到拉丁名词。',A(CONFIGURATION,'英语 re- + configuration → reconfiguration','既有布局、设置的重新组合'),'the reconfiguration of a network 说网络配置的更改；the reconfiguration of a workspace 说工作空间重新布局。正式文章也会用它描述组织力量或结构的重组。','the reconfiguration of；network reconfiguration；a major reconfiguration；require reconfiguration。','replacement 强调换掉东西；reconfiguration 强调重新安排关系与设置，原有部件可以继续使用。',('The office reconfiguration created two quiet rooms without adding more floor space.','办公室重新布局后多了两间安静室，却没有增加使用面积。'),('The upgrade requires a brief reconfiguration of the reporting system.','这次升级需要对报表系统作一次简短的重新配置。'),sources=[K('reconfiguration'),M('reconfiguration'),S('configuration'),S('reconfigure')]),
E('disfigure','英 /dɪsˈfɪɡə/；美 /dɪsˈfɪɡjər/','损坏外貌；使变形、变丑','原有的形状或面貌被破坏了，以至于外观看起来明显不同；常用于脸、雕像、建筑或景观。','中世纪拉丁 diffigurare 由 dis- 与 figurare“塑造”构成，前缀在 f 前同化；经古法语 desfigurer 等进入中古英语 disfiguren。现代可联想 dis- + figure，但真实借入经过法语动词。',DISFIGURE,'disfigure a statue 是破坏雕像外形；a scar can disfigure a face 说疤痕明显改变面貌。用到人时通常描述外貌受损，不表示这个人的人格或价值改变。','disfigure a face；disfigure a statue；be disfigured by；badly disfigure。','damage 范围很宽，包括功能损坏；disfigure 特别落在可见的外形。毁坏一台机器内部线路，未必 disfigure 它。',('Graffiti had disfigured the front of the old theatre.','涂鸦破坏了老剧院正面的外观。'),('The falling branch disfigured the garden statue but did not knock it over.','掉落的树枝损坏了花园雕像的外形，却没有把它撞倒。'),sources=[S('disfigure'),K('disfigure'),O('disfigure')]),
E('disfigured','英 /dɪsˈfɪɡəd/；美 /dɪsˈfɪɡjərd/','外形受损的；面貌明显改变的','看见的是损坏留下的结果：原来的轮廓、表面或面貌已经被改变。','disfigure + -ed，过去式、过去分词及形容词；末尾 e 后加 d，读音结尾为 /d/。',A(DISFIGURE,'英语 disfigure + -ed → disfigured','因损坏而变形、外观受损的'),'a disfigured statue 是外形遭损的雕像；be disfigured by scars 说明疤痕改变了外貌。这个词本身不说明变化是否还能修复。','a disfigured statue；a disfigured face；badly disfigured；disfigured by。','deformed 常说形状异常或变形，原因可以很多；disfigured 更常强调损伤使外观发生不利变化。不要把两者当成所有语境都相同。',('The conservator carefully examined the disfigured statue.','文物修复人员仔细检查了那尊外形受损的雕像。'),('The building’s stone doorway was badly disfigured by years of neglect.','多年失修使建筑的石门框外观严重受损。'),sources=[K('disfigured'),M('disfigured'),S('disfigure')]),
E('disfigurement','英 /dɪsˈfɪɡəmənt/；美 /dɪsˈfɪɡjərmənt/','外貌损伤；毁容；外形破坏','把“外形被破坏”当作一件事或一种后果来谈，可能是面部的损伤，也可能是物体、景观的外观受损。','英语 disfigure + -ment，动作及结果名词。来源沿英语动词这一支，不要为了看起来整齐而虚构一个必须先存在的拉丁名词。',A(DISFIGURE,'英语 disfigure + -ment → disfigurement','外观遭破坏的过程或结果'),'facial disfigurement 是面部外观损伤；the disfigurement of a landscape 可以说景观被破坏。这个词通常比普通 change 更明显带有损害意味。','facial disfigurement；permanent disfigurement；cause disfigurement；the disfigurement of。','injury 说损伤本身，未必可见；disfigurement 聚焦外貌受到的影响。scarring 是留疤，可能导致 disfigurement，但不是所有小疤痕都要这样形容。',('The charity supports people living with facial disfigurement.','这家慈善机构帮助面部外貌受损的人。'),('The report criticised the disfigurement of the valley by abandoned industrial sites.','报告批评废弃工业场地破坏了山谷的景观。'),sources=[S('disfigurement'),K('disfigurement'),O('disfigurement')]),
E('transfigure','英 /trænsˈfɪɡə/；美 /trænsˈfɪɡjər/','使面貌大变；使焕然生辉','像同一个东西突然换了光：轮廓可能还在，但整体面貌变得更美、更有光彩，或带上精神上的新意义。','拉丁 trans- 与 figurare 组成 transfigurare“改变形状”，经法语或直接拉丁借入中古英语。英语早期常在宗教语境出现，后来也用于光线、艺术、感情带来的变化。',TRANSFIG,'sunlight transfigures a landscape 是阳光使景物焕然生辉；a face transfigured by joy 是因喜悦而容光焕发的脸。它偏文学，比普通 change 更强调显著、带提升意味的变化。','transfigure a scene；transfigure a landscape；be transfigured by joy；transfigure into。','transform 范围更广，可好可坏，也可重组功能；transfigure 往往着重外貌、光彩或精神意味的改变。不是每次改软件设置都适合它。',('The evening light transfigured the grey buildings into a glowing skyline.','暮色中的光把灰色楼群映成一片发亮的天际线。'),('Her face was transfigured by joy when she saw her son.','见到儿子时，喜悦使她整张脸都焕发了光彩。'),sources=[S('transfigure'),K('transfigure'),O('transfigure')]),
E('transfiguration','英 /ˌtrænsˌfɪɡəˈreɪʃən/；美 /ˌtrænsˌfɪɡjəˈreɪʃən/','形貌的巨大转变；焕然一新；显圣容〔基督教语境〕','说一种变化，变化后仿佛显出了原先看不到的光彩；在宗教叙述里，这也可以指神圣面貌的显现。','拉丁 transfigurare 的动作名词 transfiguratio、transfigurationem，经古法语及盎格鲁法语 transfiguracion、transfiguraciun 等进入中古英语。名词独立借入，不是现代英语 transfigure 才加后缀造出的。',TRANSFIGLAT+[['拉丁 transfiguratio／transfigurationem → 法语 transfiguracion 等','形貌改变这一事件'],['中古英语 transfiguracioun → 英语 transfiguration','形貌转变；宗教中的显圣容']],'普通文学用法可说 the transfiguration of a place。大写 the Transfiguration 在基督教语境指耶稣在门徒面前显现荣耀形貌的事件，是特定宗教名称。','the transfiguration of；undergo a transfiguration；a painting of the Transfiguration。','transformation 是较普通的变化、转型；transfiguration 常突出面貌或精神层面的升华，或落在特定宗教叙述中。',('Sunrise brought a brief transfiguration of the quiet harbour.','日出让宁静的港湾短暂地焕发出另一番光彩。'),('The guide explained the scene in the painting of the Transfiguration.','导览员讲解了那幅描绘耶稣显圣容的画作中的场景。'),sources=[S('transfiguration'),K('transfiguration'),O('transfiguration')]),
]
EXCLUDE={}
ROOT=dict(id='C0422',meaning='塑造；制成某种形状；编造',core='拉丁 fingere 的起点是把材料塑成形，也能指编造、假装；相关的 figura 则落在做出来的形状、形象上。',image='手里塑形 → figure、figurine；脑中造故事 → fiction、figment；装出一种样子 → feign；重新安排形态 → configure。',intro='这一族分两条看最清楚：fict-、fing- 常通向编造和假装，figur- 常保留形状、形象。不要把词源当成今天的定义：figure 的数字义、faint 的微弱义都经过了自己的发展。',forms='fing- 见拉丁动词 fingere；fict- 来自分词 fictus，保留在 fiction、fictitious。fig- 与 figur- 见相关名词 figura 及其后代。feign、feint、faint 经法语变化后外形缩短，现代意思需要分别掌握。',branches=[['形式、图像与表达','figure, figurative, figuratively, figurehead, figurine, effigy'],['造出故事与想象物','fiction, fictional, fictitious, fictionalize, fictionalization, figment, nonfiction'],['装出样子；历史上走向虚弱的旁支','feign, feigned, feint, faint, faintly, faintness'],['安排形态与配置','configure, configured, configuration, configurable, reconfigure, reconfiguration'],['外貌改变','disfigure, disfigured, disfigurement, transfigure, transfiguration']],contrasts='fictional 常说故事中的虚构；fictitious 常说资料、名字或说法是编出的。figure out 是想明白，configure 是配置。feint 是假动作，faint 是微弱或晕倒；同源关系不能抹掉现代差别。',practice='A fictional figure is not a numerical figure. 前者是故事中虚构的人物，后者是数值；把 figure 的“呈现形式”放进具体搭配，意思就会清楚。',words=[],exclude=EXCLUDE)
